const apiKey = env.get('INGEST_API_KEY');
const incomingKey = msg.req?.headers?.['x-api-key'] || '';

function safeCompare(a, b) {
    if (typeof a !== 'string' || typeof b !== 'string') return false;
    if (a.length !== b.length) return false;
    let mismatch = 0;
    for (let i = 0; i < a.length; i++) {
        mismatch |= (a.charCodeAt(i) ^ b.charCodeAt(i));
    }
    return mismatch === 0;
}

if (!apiKey || !safeCompare(incomingKey, apiKey)) {
    msg.statusCode = 401;
    msg.payload = { error: 'Unauthorized' };
    return msg;
}

if (!msg.payload || !Array.isArray(msg.payload)) {
    msg.statusCode = 400;
    msg.payload = { error: 'Payload must be a JSON array' };
    return msg;
}

// One INSERT binds 36 parameters per row; PostgreSQL allows 65,535 per
// statement, so a batch over ~1,800 rows failed as a whole. Cap well below.
const MAX_ROWS = 1000;
if (msg.payload.length > MAX_ROWS) {
    msg.statusCode = 413;
    msg.payload = { error: 'Batch too large: ' + msg.payload.length + ' rows, max ' + MAX_ROWS + ' -- split it' };
    return msg;
}

// Every row needs its identity: ldi_data's key is (log_id, time), so a row
// with an empty log_id cannot be de-duplicated on replay. Reject the batch and
// name the rows, instead of silently dropping or accepting them.
const invalid = [];
msg.payload.forEach((item, i) => {
    if (!item || typeof item !== 'object' || !item.eqp_id || item.log_id === undefined || item.log_id === null || String(item.log_id) === '') invalid.push(i);
});
if (invalid.length > 0) {
    msg.statusCode = 400;
    msg.payload = { error: 'Rows missing eqp_id or log_id', rows: invalid.slice(0, 50), count: invalid.length };
    return msg;
}

msg._ldiBatch = [];
// "0", "0.0" and 0 are real zeros; only absent/empty/non-numeric is NULL
// (Number("0") || null used to turn string zeros into NULL).
const num = v => (v === null || v === undefined || v === '' || typeof v === 'boolean') ? null : (Number.isFinite(Number(v)) ? Number(v) : null);
const int = v => { const n = num(v); return n === null ? null : Math.trunc(n); };
// nullable text columns keep NULL instead of '' (filmno/board_id are NULL at source)
const optText = v => (v === null || v === undefined || v === '') ? null : String(v);
// state is a machine state, not a default: a missing value is unknown (NULL),
// not "running" -- defaulting to true inflated uptime
const bool = v => (typeof v === 'boolean') ? v : (v === 'true' || v === 1 || v === '1') ? true : (v === 'false' || v === 0 || v === '0') ? false : null;
for (const item of msg.payload) {
    msg._ldiBatch.push({
        // Real per-record source timestamp from the producer (ldisim_gen
        // sets this to when the reading was actually generated). Was
        // previously discarded in favor of a single server-side NOW()
        // shared by every row in the batch -- fixed here, see migration 081.
        time: item.time ? new Date(item.time).toISOString() : new Date().toISOString(),
        eqp_id: String(item.eqp_id),
        factory: String(item.factory || ''),
        process: String(item.process || ''),
        mo: String(item.mo || ''),
        fpn: String(item.fpn || ''),
        layer_name: String(item.layer_name || ''),
        resist_dosage: num(item.resist_dosage),
        scale_x: num(item.scale_x),
        scale_y: num(item.scale_y),
        temperature: num(item.temperature),
        humidity: num(item.humidity),
        scan_speed: num(item.scan_speed),
        air_vacuum: num(item.air_vacuum),
        thickness: num(item.thickness),
        board_no: int(item.board_no),
        total_board: int(item.total_board),
        total_time: num(item.total_time),
        filmno: optText(item.filmno),
        board_id: optText(item.board_id),
        resist: item.resist ? String(item.resist) : null,
        state: bool(item.state),
        scale_mode: String(item.scale_mode || ''),
        pe_1: num(item.pe_1),
        pe_2: num(item.pe_2),
        pe_3: num(item.pe_3),
        pe_4: num(item.pe_4),
        pe_5: num(item.pe_5),
        pe_6: num(item.pe_6),
        je_1: num(item.je_1),
        je_2: num(item.je_2),
        je_3: num(item.je_3),
        je_4: num(item.je_4),
        pe_setting: num(item.pe_setting),
        je_setting: num(item.je_setting),
        log_id: String(item.log_id)
    });
}


if (msg._ldiBatch.length === 0) {
    msg.statusCode = 200;
    msg.payload = { message: 'Empty batch' };
    return msg;
}

const cols = [
    'time', 'factory', 'process', 'eqp_id', 'mo', 'fpn', 'layer_name', 'resist_dosage', 'scale_x', 'scale_y',
    'temperature', 'humidity', 'scan_speed', 'air_vacuum', 'thickness', 'board_no', 'total_board',
    'total_time', 'filmno', 'board_id', 'resist', 'state', 'scale_mode',
    'pe_1', 'pe_2', 'pe_3', 'pe_4', 'pe_5', 'pe_6',
    'je_1', 'je_2', 'je_3', 'je_4', 'pe_setting', 'je_setting', 'log_id'
];

let params = [];
const placeholders = msg._ldiBatch.map((row, i) => {
    const b = i * cols.length;
    cols.forEach(col => params.push(row[col]));
    const p = cols.map((_, j) => `$${b + j + 1}`).join(',');
    return `(${p})`;
}).join(',');

// ingest_ts: real server commit time, set explicitly (not a DB default --
// ldi_data is a compressed hypertable, see migration 081's comment on why).
msg.query = `INSERT INTO public.ldi_data (${cols.join(',')}, ingest_ts) VALUES ` +
    msg._ldiBatch.map((_, i) => {
        const b = i * cols.length;
        return `(${cols.map((_, j) => `$${b + j + 1}`).join(',')}, clock_timestamp())`;
    }).join(',') +
    ` ON CONFLICT (log_id, "time") DO NOTHING;`;
msg.params = params;

// Earliest source_ts in this batch, for the staging row -- good enough to
// bound how stale a replay is; per-row fidelity is preserved in the
// staged payload itself (msg._ldiBatch, which still carries each row's
// own `time`).
const earliestSourceTs = msg._ldiBatch.reduce((min, r) => r.time < min ? r.time : min, msg._ldiBatch[0].time);

const pool = global.get('pgPool');
if (!pool) {
    msg.statusCode = 503;
    msg.payload = { error: 'DB pool unavailable' };
    return msg;
}

const nodeRef = node;
const msgRef = msg;

// Stage BEFORE attempting the real insert -- durable write-ahead copy.
// A crash between here and the real INSERT's commit leaves this row
// recoverable (see the staging-replay flow) instead of silently gone.
pool.query(
    `INSERT INTO public.ingest_staging (target_table, payload, source_ts) VALUES ($1, $2, $3) RETURNING id`,
    ['ldi_data', JSON.stringify(msgRef._ldiBatch), earliestSourceTs],
    function (stageErr, stageResult) {
        if (stageErr) {
            // Couldn't even stage -- DB is unreachable. Tell the truth: fail
            // the HTTP call so the caller knows this batch did not land,
            // rather than the old fire-and-forget 200.
            nodeRef.error('LDI staging INSERT failed: ' + stageErr.message);
            msgRef.statusCode = 503;
            msgRef.payload = { error: 'Staging failed, batch not accepted' };
            nodeRef.send(msgRef);
            nodeRef.done();
            return;
        }
        const stagingId = stageResult.rows[0].id;
        pool.query(msgRef.query, msgRef.params, (err) => {
            if (err) {
                nodeRef.error('LDI INSERT failed: ' + err.message);
                // Auto-recovery watchdog for a specific, live-verified failure mode:
                // this global pg.Pool can get permanently stuck after a
                // Postgres/PgBouncer restart or connection blip ("server login
                // has been failing, cached error: connect failed") -- confirmed
                // 2026-08-10 that PgBouncer itself recovers within 1-3 minutes but
                // this pool does not follow; only a full Node-RED process restart
                // clears it. Scoped to this connection-failure signature
                // specifically (not e.g. constraint violations, which a restart
                // wouldn't fix and would just mask).
                if (/server login has been failing|connect failed|ECONNREFUSED|ECONNRESET|timeout expired/i.test(err.message)) {
                    const streak = (global.get('ldiDbConnFailureStreak') || 0) + 1;
                    global.set('ldiDbConnFailureStreak', streak);
                    const FAILURE_THRESHOLD = 5;
                    if (streak >= FAILURE_THRESHOLD) {
                        // Replace the stuck pool with a fresh one built from the same
                        // config. Exiting the process used to recover it, but also took
                        // SNMP polling and alerting down, and during a long DB outage
                        // turned into a restart loop.
                        const pg = global.get('pg');
                        const stuck = global.get('pgPool');
                        if (pg && stuck && stuck.options) {
                            const fresh = new pg.Pool(stuck.options);
                            fresh.on('error', (e) => nodeRef.warn('pg pool idle-client error (non-fatal): ' + e.message));
                            global.set('pgPool', fresh);
                            global.set('ldiDbConnFailureStreak', 0);
                            nodeRef.error('LDI INSERT connection failure x' + streak + ' in a row -- replaced the DB pool');
                            stuck.end().catch(() => {});
                        }
                    }
                } else {
                    global.set('ldiDbConnFailureStreak', 0);
                }
                // Leave the staged row as 'pending' -- the periodic replay
                // sweep (ldi_staging_replay) will retry it. Tell the caller
                // the truth: this batch did not land yet.
                pool.query(
                    `UPDATE public.ingest_staging SET attempts = attempts + 1, last_error = $2 WHERE id = $1`,
                    [stagingId, String(err.message).slice(0, 500)],
                    () => {}
                );
                msgRef.statusCode = 502;
                msgRef.payload = { error: 'Insert failed, batch staged for retry' };
                nodeRef.send(msgRef);
                nodeRef.done();
                return;
            }
            global.set('ldiDbConnFailureStreak', 0);
            // Confirmed committed -- delete the staged copy.
            pool.query(`DELETE FROM public.ingest_staging WHERE id = $1`, [stagingId], () => {});
            msgRef.statusCode = 200;
            msgRef.payload = { message: 'LDI Batch received', rows: msgRef._ldiBatch.length };
            nodeRef.send(msgRef);
            nodeRef.done();
        });
    }
);
return null;

const err = msg.error?.message || 'Unknown error';
node.error('LDI INSERT failed: ' + err);
msg.statusCode = 500;
msg.payload = { error: err };
return msg;
